-- Baseline schema for an EMPTY database: every type, table, column, index and foreign key of db/schema.ts.
-- Generated by `npm run db:export-schema`. Do not edit by hand; change db/schema.ts and regenerate.
-- Applied by `npm run db:init` (scripts/db-init.ts) only when the database has no tables yet.
-- The reporting views are not here: db/views.sql re-creates them on every `db:init`.

CREATE TYPE "public"."answer_role" AS ENUM('technical', 'functional', 'product');
CREATE TYPE "public"."card_audience" AS ENUM('functional', 'technical');
CREATE TYPE "public"."card_level" AS ENUM('easy', 'medium', 'hard');
CREATE TYPE "public"."card_status" AS ENUM('active', 'retired', 'draft');
CREATE TYPE "public"."chat_feedback_value" AS ENUM('up', 'down');
CREATE TYPE "public"."chat_message_status" AS ENUM('ok', 'streaming', 'stopped', 'error');
CREATE TYPE "public"."chat_sender" AS ENUM('user', 'assistant');
CREATE TYPE "public"."feedback_category" AS ENUM('incorrect', 'incomplete', 'outdated', 'unclear', 'other');
CREATE TYPE "public"."feedback_status" AS ENUM('open', 'accepted', 'rejected', 'applied', 'stale');
CREATE TYPE "public"."kb_item_type" AS ENUM('module', 'concept', 'rule', 'form', 'usercontrol', 'process');
CREATE TYPE "public"."user_status" AS ENUM('pending', 'active', 'disabled');
CREATE TYPE "public"."verdict" AS ENUM('correct', 'needs_improvement', 'unsure');
CREATE TABLE "activity_log" (
	"id" bigserial PRIMARY KEY NOT NULL,
	"user_id" uuid,
	"action" text NOT NULL,
	"target_type" text,
	"target_id" text,
	"details" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"session_id" text,
	"ip" text,
	"client_event_id" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "activity_log_client_event_id_unique" UNIQUE("client_event_id")
);

CREATE TABLE "app_settings" (
	"key" text PRIMARY KEY NOT NULL,
	"value" jsonb NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "card_feedback" (
	"id" serial PRIMARY KEY NOT NULL,
	"review_id" bigint,
	"user_id" uuid NOT NULL,
	"card_version_id" integer NOT NULL,
	"category" "feedback_category" NOT NULL,
	"suggested_text" text,
	"comment" text,
	"status" "feedback_status" DEFAULT 'open' NOT NULL,
	"resolved_by" uuid,
	"resolved_at" timestamp with time zone,
	"resolution_note" text,
	"applied_commit" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "card_related_items" (
	"card_id" text NOT NULL,
	"kb_item_id" integer NOT NULL,
	"relation" text NOT NULL,
	CONSTRAINT "card_related_items_card_id_kb_item_id_relation_pk" PRIMARY KEY("card_id","kb_item_id","relation")
);

CREATE TABLE "card_reviews" (
	"id" bigserial PRIMARY KEY NOT NULL,
	"user_id" uuid NOT NULL,
	"card_version_id" integer NOT NULL,
	"deck_id" integer,
	"source" text DEFAULT 'daily' NOT NULL,
	"knew_it" boolean NOT NULL,
	"verdict" "verdict" NOT NULL,
	"shown_at" timestamp with time zone,
	"flipped_at" timestamp with time zone,
	"answered_at" timestamp with time zone,
	"client_event_id" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "card_reviews_client_event_id_unique" UNIQUE("client_event_id")
);

CREATE TABLE "card_versions" (
	"id" serial PRIMARY KEY NOT NULL,
	"card_id" text NOT NULL,
	"version" integer NOT NULL,
	"context" text NOT NULL,
	"front" text NOT NULL,
	"back" text NOT NULL,
	"source_text" text NOT NULL,
	"source_hash" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "card_versions_card_version" UNIQUE("card_id","version")
);

CREATE TABLE "cards" (
	"id" text PRIMARY KEY NOT NULL,
	"kb_item_id" integer NOT NULL,
	"kind" text NOT NULL,
	"source_field" text NOT NULL,
	"audience" "card_audience",
	"level" "card_level",
	"topic_key" text,
	"status" "card_status" DEFAULT 'active' NOT NULL,
	"current_version_id" integer,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "chat_feedback" (
	"id" serial PRIMARY KEY NOT NULL,
	"message_id" bigint NOT NULL,
	"user_id" uuid NOT NULL,
	"value" "chat_feedback_value" NOT NULL,
	"comment" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "chat_messages" (
	"id" bigserial PRIMARY KEY NOT NULL,
	"conversation_id" uuid NOT NULL,
	"sender" "chat_sender" NOT NULL,
	"reply_to_id" bigint,
	"content" text DEFAULT '' NOT NULL,
	"status" "chat_message_status" DEFAULT 'ok' NOT NULL,
	"error_code" text,
	"tokens_in" integer,
	"tokens_out" integer,
	"duration_ms" integer,
	"num_turns" integer,
	"model" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"completed_at" timestamp with time zone
);

CREATE TABLE "chat_tool_calls" (
	"id" bigserial PRIMARY KEY NOT NULL,
	"message_id" bigint NOT NULL,
	"tool_use_id" text,
	"tool_name" text NOT NULL,
	"arguments" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"allowed" boolean NOT NULL,
	"is_error" boolean,
	"duration_ms" integer,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "conversations" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"title" text NOT NULL,
	"role_used" "answer_role" NOT NULL,
	"claude_session_id" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone
);

CREATE TABLE "daily_decks" (
	"id" serial PRIMARY KEY NOT NULL,
	"user_id" uuid NOT NULL,
	"session_id" text,
	"deck_date" date NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"completed_at" timestamp with time zone
);

CREATE TABLE "deck_cards" (
	"deck_id" integer NOT NULL,
	"card_id" text NOT NULL,
	"position" integer NOT NULL,
	CONSTRAINT "deck_cards_deck_id_card_id_pk" PRIMARY KEY("deck_id","card_id")
);

CREATE TABLE "kb_items" (
	"id" serial PRIMARY KEY NOT NULL,
	"type" "kb_item_type" NOT NULL,
	"key" text NOT NULL,
	"name" text NOT NULL,
	"module" text,
	"yaml_file" text NOT NULL,
	"content_hash" text NOT NULL,
	"meta" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"active" boolean DEFAULT true NOT NULL,
	CONSTRAINT "kb_items_type_key" UNIQUE("type","key")
);

CREATE TABLE "login_sessions" (
	"id" text PRIMARY KEY NOT NULL,
	"user_id" uuid NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "refresh_tokens" (
	"id" text PRIMARY KEY NOT NULL,
	"session_id" text NOT NULL,
	"idle_expires_at" timestamp with time zone NOT NULL,
	"used_at" timestamp with time zone,
	"replaced_by_id" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "review_schedule" (
	"user_id" uuid NOT NULL,
	"card_id" text NOT NULL,
	"box" integer DEFAULT 1 NOT NULL,
	"due_date" date NOT NULL,
	"reps" integer DEFAULT 0 NOT NULL,
	"lapses" integer DEFAULT 0 NOT NULL,
	CONSTRAINT "review_schedule_user_id_card_id_pk" PRIMARY KEY("user_id","card_id")
);

CREATE TABLE "roles" (
	"id" serial PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	CONSTRAINT "roles_name_unique" UNIQUE("name")
);

CREATE TABLE "users" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"username" text NOT NULL,
	"password_hash" text NOT NULL,
	"display_name" text NOT NULL,
	"department" text,
	"primary_module" text,
	"answer_role" "answer_role",
	"role_id" integer NOT NULL,
	"status" "user_status" DEFAULT 'active' NOT NULL,
	"last_login_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "users_username_unique" UNIQUE("username")
);

