CREATE INDEX "activity_log_user_idx" ON "activity_log" USING btree ("user_id","created_at");
CREATE INDEX "activity_log_action_idx" ON "activity_log" USING btree ("action","created_at");
CREATE INDEX "card_feedback_version_idx" ON "card_feedback" USING btree ("card_version_id","status");
CREATE INDEX "card_feedback_status_idx" ON "card_feedback" USING btree ("status");
CREATE INDEX "card_related_items_item_idx" ON "card_related_items" USING btree ("kb_item_id");
CREATE INDEX "card_reviews_user_idx" ON "card_reviews" USING btree ("user_id","created_at");
CREATE INDEX "card_reviews_version_idx" ON "card_reviews" USING btree ("card_version_id");
CREATE UNIQUE INDEX "card_reviews_deck_version" ON "card_reviews" USING btree ("deck_id","card_version_id");
CREATE INDEX "cards_kb_item_idx" ON "cards" USING btree ("kb_item_id");
CREATE INDEX "cards_status_idx" ON "cards" USING btree ("status");
CREATE UNIQUE INDEX "cards_generated_identity" ON "cards" USING btree ("kb_item_id","audience","level","topic_key") WHERE "cards"."audience" IS NOT NULL;
CREATE UNIQUE INDEX "chat_feedback_msg_user" ON "chat_feedback" USING btree ("message_id","user_id");
